CREATE TABLE practice_assignments(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),customer_id TEXT NOT NULL REFERENCES customers(id),plan_id TEXT NOT NULL,plan_version INTEGER NOT NULL,cycle_id TEXT NOT NULL,cycle_version INTEGER NOT NULL,owner_id TEXT NOT NULL REFERENCES users(id),recipient_id TEXT NOT NULL REFERENCES users(id),session_id TEXT REFERENCES training_sessions(id),session_revision INTEGER,serial INTEGER NOT NULL,practice_number TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,serial),UNIQUE(id,store_id),FOREIGN KEY(plan_id,plan_version) REFERENCES training_plan_versions(plan_id,version),FOREIGN KEY(cycle_id,cycle_version) REFERENCES cycle_versions(cycle_id,version),FOREIGN KEY(session_id,session_revision) REFERENCES training_session_events(session_id,revision),CHECK((session_id IS NULL AND session_revision IS NULL) OR (session_id IS NOT NULL AND session_revision IS NOT NULL)));
CREATE TABLE practice_versions(assignment_id TEXT NOT NULL,store_id TEXT NOT NULL,version INTEGER NOT NULL CHECK(version>0),base_sequence INTEGER NOT NULL CHECK(base_sequence>=0),title TEXT NOT NULL,instructions TEXT NOT NULL,due_date TEXT,source_note TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),PRIMARY KEY(assignment_id,version),FOREIGN KEY(assignment_id,store_id) REFERENCES practice_assignments(id,store_id),CHECK(due_date IS NULL OR(length(due_date)=10 AND date(due_date,'+0 days') IS due_date)));
CREATE TABLE practice_events(id TEXT PRIMARY KEY,assignment_id TEXT NOT NULL,store_id TEXT NOT NULL,revision INTEGER NOT NULL,sequence INTEGER NOT NULL,action TEXT NOT NULL CHECK(action IN('create','revise','publish','withdraw','close')),version INTEGER NOT NULL,released_version INTEGER,status TEXT NOT NULL CHECK(status IN('draft','published','withdrawn','closed')),note TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(assignment_id,revision),UNIQUE(store_id,sequence),FOREIGN KEY(assignment_id,store_id) REFERENCES practice_assignments(id,store_id),FOREIGN KEY(assignment_id,version) REFERENCES practice_versions(assignment_id,version),FOREIGN KEY(assignment_id,released_version) REFERENCES practice_versions(assignment_id,version));
CREATE TABLE practice_reports(id TEXT PRIMARY KEY,assignment_id TEXT NOT NULL,store_id TEXT NOT NULL,sequence INTEGER NOT NULL,serial INTEGER NOT NULL,assignment_revision INTEGER NOT NULL,version INTEGER NOT NULL,source TEXT NOT NULL CHECK(source IN('guardian_self_report','guardian_transcript','staff_observation','device_transcript')),source_note TEXT NOT NULL,occurred_at TEXT NOT NULL,minutes INTEGER CHECK(minutes IS NULL OR(typeof(minutes)='integer' AND minutes BETWEEN 0 AND 1440)),completion TEXT NOT NULL CHECK(completion IN('completed','partial','not_done','unknown')),feedback TEXT NOT NULL,contact_requested INTEGER NOT NULL CHECK(contact_requested IN(0,1)),reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(assignment_id,serial),UNIQUE(store_id,sequence),FOREIGN KEY(assignment_id,store_id) REFERENCES practice_assignments(id,store_id),FOREIGN KEY(assignment_id,version) REFERENCES practice_versions(assignment_id,version),FOREIGN KEY(assignment_id,assignment_revision) REFERENCES practice_events(assignment_id,revision));
CREATE TABLE practice_reviews(id TEXT PRIMARY KEY,report_id TEXT NOT NULL REFERENCES practice_reports(id),store_id TEXT NOT NULL REFERENCES stores(id),revision INTEGER NOT NULL,sequence INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN('noted','needs_followup')),internal_note TEXT NOT NULL,family_feedback TEXT,share_feedback INTEGER NOT NULL CHECK(share_feedback IN(0,1)),followup_task_id TEXT REFERENCES work_tasks(id),followup_revision INTEGER,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(report_id,revision),UNIQUE(store_id,sequence),CHECK((followup_task_id IS NULL AND followup_revision IS NULL) OR (followup_task_id IS NOT NULL AND followup_revision IS NOT NULL)),CHECK((share_feedback=1 AND family_feedback IS NOT NULL) OR (share_feedback=0 AND family_feedback IS NULL)),CHECK(status!='needs_followup' OR followup_task_id IS NOT NULL));
CREATE TABLE training_reassessments(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),customer_id TEXT NOT NULL REFERENCES customers(id),plan_id TEXT NOT NULL,plan_version INTEGER NOT NULL,cycle_id TEXT NOT NULL,cycle_version INTEGER NOT NULL,owner_id TEXT NOT NULL REFERENCES users(id),serial INTEGER NOT NULL,reassessment_number TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,serial),UNIQUE(id,store_id),FOREIGN KEY(plan_id,plan_version) REFERENCES training_plan_versions(plan_id,version),FOREIGN KEY(cycle_id,cycle_version) REFERENCES cycle_versions(cycle_id,version));
CREATE TABLE training_reassessment_versions(reassessment_id TEXT NOT NULL,store_id TEXT NOT NULL,version INTEGER NOT NULL CHECK(version>0),base_sequence INTEGER NOT NULL,title TEXT NOT NULL,source_note TEXT NOT NULL,comparison_note TEXT NOT NULL,assessment_note TEXT NOT NULL,next_step TEXT NOT NULL,direction TEXT NOT NULL CHECK(direction IN('continue_record','adjustment_review','ending_review','needs_information')),manifest_json TEXT NOT NULL CHECK(json_valid(manifest_json)),reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),PRIMARY KEY(reassessment_id,version),FOREIGN KEY(reassessment_id,store_id) REFERENCES training_reassessments(id,store_id));
CREATE TABLE training_reassessment_events(id TEXT PRIMARY KEY,reassessment_id TEXT NOT NULL,store_id TEXT NOT NULL,revision INTEGER NOT NULL,sequence INTEGER NOT NULL,version INTEGER NOT NULL,action TEXT NOT NULL CHECK(action IN('create','revise','check')),status TEXT NOT NULL CHECK(status IN('draft','checked')),note TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(reassessment_id,revision),UNIQUE(store_id,sequence),FOREIGN KEY(reassessment_id,store_id) REFERENCES training_reassessments(id,store_id),FOREIGN KEY(reassessment_id,version) REFERENCES training_reassessment_versions(reassessment_id,version));
CREATE VIEW family_journal AS SELECT store_id,sequence,created_at,'practice' kind,assignment_id root_id,id FROM practice_events UNION ALL SELECT store_id,sequence,created_at,'report',assignment_id,id FROM practice_reports UNION ALL SELECT store_id,sequence,created_at,'review',report_id,id FROM practice_reviews UNION ALL SELECT store_id,sequence,created_at,'reassessment',reassessment_id,id FROM training_reassessment_events;
CREATE VIEW practice_current AS SELECT * FROM practice_events e WHERE revision=(SELECT max(revision) FROM practice_events WHERE assignment_id=e.assignment_id);
CREATE VIEW reassessment_current AS SELECT * FROM training_reassessment_events e WHERE revision=(SELECT max(revision) FROM training_reassessment_events WHERE reassessment_id=e.reassessment_id);
CREATE INDEX practice_customer ON practice_assignments(customer_id,serial);
CREATE INDEX practice_recipient ON practice_assignments(recipient_id,customer_id);
CREATE TRIGGER practice_assignments_no_update BEFORE UPDATE ON practice_assignments BEGIN SELECT RAISE(ABORT,'immutable family history'); END;
CREATE TRIGGER practice_assignments_no_delete BEFORE DELETE ON practice_assignments BEGIN SELECT RAISE(ABORT,'immutable family history'); END;
CREATE TRIGGER practice_assignments_actor BEFORE INSERT ON practice_assignments WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=NEW.created_by AND u.active=1 AND u.store_id=NEW.store_id AND u.role IN('professional') AND COALESCE(x.must_change_password,0)=0) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') BEGIN SELECT RAISE(ABORT,'family actor/time mismatch'); END;
CREATE TRIGGER practice_versions_no_update BEFORE UPDATE ON practice_versions BEGIN SELECT RAISE(ABORT,'immutable family history'); END;
CREATE TRIGGER practice_versions_no_delete BEFORE DELETE ON practice_versions BEGIN SELECT RAISE(ABORT,'immutable family history'); END;
CREATE TRIGGER practice_versions_actor BEFORE INSERT ON practice_versions WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=NEW.created_by AND u.active=1 AND u.store_id=NEW.store_id AND u.role IN('professional') AND COALESCE(x.must_change_password,0)=0) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') BEGIN SELECT RAISE(ABORT,'family actor/time mismatch'); END;
CREATE TRIGGER practice_events_no_update BEFORE UPDATE ON practice_events BEGIN SELECT RAISE(ABORT,'immutable family history'); END;
CREATE TRIGGER practice_events_no_delete BEFORE DELETE ON practice_events BEGIN SELECT RAISE(ABORT,'immutable family history'); END;
CREATE TRIGGER practice_events_actor BEFORE INSERT ON practice_events WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=NEW.created_by AND u.active=1 AND u.store_id=NEW.store_id AND u.role IN('manager','professional') AND COALESCE(x.must_change_password,0)=0) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') BEGIN SELECT RAISE(ABORT,'family actor/time mismatch'); END;
CREATE TRIGGER practice_reports_no_update BEFORE UPDATE ON practice_reports BEGIN SELECT RAISE(ABORT,'immutable family history'); END;
CREATE TRIGGER practice_reports_no_delete BEFORE DELETE ON practice_reports BEGIN SELECT RAISE(ABORT,'immutable family history'); END;
CREATE TRIGGER practice_reports_actor BEFORE INSERT ON practice_reports WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=NEW.created_by AND u.active=1 AND (u.store_id=NEW.store_id OR u.role='guardian') AND u.role IN('manager','reception','professional','guardian') AND COALESCE(x.must_change_password,0)=0) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') BEGIN SELECT RAISE(ABORT,'family actor/time mismatch'); END;
CREATE TRIGGER practice_reviews_no_update BEFORE UPDATE ON practice_reviews BEGIN SELECT RAISE(ABORT,'immutable family history'); END;
CREATE TRIGGER practice_reviews_no_delete BEFORE DELETE ON practice_reviews BEGIN SELECT RAISE(ABORT,'immutable family history'); END;
CREATE TRIGGER practice_reviews_actor BEFORE INSERT ON practice_reviews WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=NEW.created_by AND u.active=1 AND u.store_id=NEW.store_id AND u.role IN('professional') AND COALESCE(x.must_change_password,0)=0) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') BEGIN SELECT RAISE(ABORT,'family actor/time mismatch'); END;
CREATE TRIGGER training_reassessments_no_update BEFORE UPDATE ON training_reassessments BEGIN SELECT RAISE(ABORT,'immutable family history'); END;
CREATE TRIGGER training_reassessments_no_delete BEFORE DELETE ON training_reassessments BEGIN SELECT RAISE(ABORT,'immutable family history'); END;
CREATE TRIGGER training_reassessments_actor BEFORE INSERT ON training_reassessments WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=NEW.created_by AND u.active=1 AND u.store_id=NEW.store_id AND u.role IN('professional') AND COALESCE(x.must_change_password,0)=0) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') BEGIN SELECT RAISE(ABORT,'family actor/time mismatch'); END;
CREATE TRIGGER training_reassessment_versions_no_update BEFORE UPDATE ON training_reassessment_versions BEGIN SELECT RAISE(ABORT,'immutable family history'); END;
CREATE TRIGGER training_reassessment_versions_no_delete BEFORE DELETE ON training_reassessment_versions BEGIN SELECT RAISE(ABORT,'immutable family history'); END;
CREATE TRIGGER training_reassessment_versions_actor BEFORE INSERT ON training_reassessment_versions WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=NEW.created_by AND u.active=1 AND u.store_id=NEW.store_id AND u.role IN('professional') AND COALESCE(x.must_change_password,0)=0) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') BEGIN SELECT RAISE(ABORT,'family actor/time mismatch'); END;
CREATE TRIGGER training_reassessment_events_no_update BEFORE UPDATE ON training_reassessment_events BEGIN SELECT RAISE(ABORT,'immutable family history'); END;
CREATE TRIGGER training_reassessment_events_no_delete BEFORE DELETE ON training_reassessment_events BEGIN SELECT RAISE(ABORT,'immutable family history'); END;
CREATE TRIGGER training_reassessment_events_actor BEFORE INSERT ON training_reassessment_events WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=NEW.created_by AND u.active=1 AND u.store_id=NEW.store_id AND u.role IN('professional') AND COALESCE(x.must_change_password,0)=0) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') BEGIN SELECT RAISE(ABORT,'family actor/time mismatch'); END;
CREATE TRIGGER practice_events_sequence BEFORE INSERT ON practice_events WHEN NEW.sequence!=(SELECT COALESCE(max(sequence),0)+1 FROM family_journal WHERE store_id=NEW.store_id) OR NEW.created_at<COALESCE((SELECT max(created_at) FROM family_journal WHERE store_id=NEW.store_id),NEW.created_at) OR (length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300) BEGIN SELECT RAISE(ABORT,'family journal mismatch'); END;
CREATE TRIGGER practice_reports_sequence BEFORE INSERT ON practice_reports WHEN NEW.sequence!=(SELECT COALESCE(max(sequence),0)+1 FROM family_journal WHERE store_id=NEW.store_id) OR NEW.created_at<COALESCE((SELECT max(created_at) FROM family_journal WHERE store_id=NEW.store_id),NEW.created_at) OR (length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300) BEGIN SELECT RAISE(ABORT,'family journal mismatch'); END;
CREATE TRIGGER practice_reviews_sequence BEFORE INSERT ON practice_reviews WHEN NEW.sequence!=(SELECT COALESCE(max(sequence),0)+1 FROM family_journal WHERE store_id=NEW.store_id) OR NEW.created_at<COALESCE((SELECT max(created_at) FROM family_journal WHERE store_id=NEW.store_id),NEW.created_at) OR (length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300) BEGIN SELECT RAISE(ABORT,'family journal mismatch'); END;
CREATE TRIGGER training_reassessment_events_sequence BEFORE INSERT ON training_reassessment_events WHEN NEW.sequence!=(SELECT COALESCE(max(sequence),0)+1 FROM family_journal WHERE store_id=NEW.store_id) OR NEW.created_at<COALESCE((SELECT max(created_at) FROM family_journal WHERE store_id=NEW.store_id),NEW.created_at) OR (length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300) BEGIN SELECT RAISE(ABORT,'family journal mismatch'); END;
CREATE TRIGGER practice_assignments_root_guard BEFORE INSERT ON practice_assignments WHEN NEW.serial!=(SELECT COALESCE(max(serial),0)+1 FROM practice_assignments WHERE store_id=NEW.store_id) OR NEW.practice_number!=('HP-'||replace(substr(NEW.created_at,1,10),'-','')||'-'||printf('%05d',NEW.serial)) OR NEW.created_by!=NEW.owner_id OR NOT EXISTS(SELECT 1 FROM training_plans p JOIN training_plan_versions v ON v.plan_id=p.id JOIN customers c ON c.id=p.customer_id WHERE p.id=NEW.plan_id AND v.version=NEW.plan_version AND p.store_id=NEW.store_id AND p.customer_id=NEW.customer_id AND c.store_id=NEW.store_id AND p.cycle_id=NEW.cycle_id AND p.cycle_version=NEW.cycle_version AND v.owner_id=NEW.owner_id AND v.created_at<=NEW.created_at) BEGIN SELECT RAISE(ABORT,'family fixed plan mismatch'); END;
CREATE TRIGGER training_reassessments_root_guard BEFORE INSERT ON training_reassessments WHEN NEW.serial!=(SELECT COALESCE(max(serial),0)+1 FROM training_reassessments WHERE store_id=NEW.store_id) OR NEW.reassessment_number!=('RA-'||replace(substr(NEW.created_at,1,10),'-','')||'-'||printf('%05d',NEW.serial)) OR NEW.created_by!=NEW.owner_id OR NOT EXISTS(SELECT 1 FROM training_plans p JOIN training_plan_versions v ON v.plan_id=p.id JOIN customers c ON c.id=p.customer_id WHERE p.id=NEW.plan_id AND v.version=NEW.plan_version AND p.store_id=NEW.store_id AND p.customer_id=NEW.customer_id AND c.store_id=NEW.store_id AND p.cycle_id=NEW.cycle_id AND p.cycle_version=NEW.cycle_version AND v.owner_id=NEW.owner_id AND v.created_at<=NEW.created_at) BEGIN SELECT RAISE(ABORT,'family fixed plan mismatch'); END;
CREATE TRIGGER practice_assignment_guard BEFORE INSERT ON practice_assignments WHEN NOT EXISTS(SELECT 1 FROM users u JOIN guardian_links g ON g.user_id=u.id WHERE u.id=NEW.recipient_id AND u.role='guardian' AND u.active=1 AND g.customer_id=NEW.customer_id AND g.active=1) OR (NEW.session_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM training_sessions s JOIN training_session_events e ON e.session_id=s.id WHERE s.id=NEW.session_id AND e.revision=NEW.session_revision AND s.plan_id=NEW.plan_id AND s.plan_version=NEW.plan_version AND s.customer_id=NEW.customer_id AND e.status IN('recorded','reviewed','aborted') AND e.created_at<=NEW.created_at)) BEGIN SELECT RAISE(ABORT,'family recipient/course mismatch'); END;
CREATE TRIGGER practice_version_guard BEFORE INSERT ON practice_versions WHEN NEW.base_sequence!=(SELECT COALESCE(max(sequence),0) FROM family_journal WHERE store_id=NEW.store_id) OR NEW.version!=(SELECT COALESCE(max(version),0)+1 FROM practice_versions WHERE assignment_id=NEW.assignment_id) OR (length(trim(NEW.title)) NOT BETWEEN 1 AND 120 OR length(NEW.title)>120) OR (length(trim(NEW.instructions)) NOT BETWEEN 1 AND 3000 OR length(NEW.instructions)>3000) OR (length(trim(NEW.source_note)) NOT BETWEEN 1 AND 1000 OR length(NEW.source_note)>1000) OR (length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300) OR NEW.created_by!=(SELECT owner_id FROM practice_assignments WHERE id=NEW.assignment_id) OR (NEW.version=1 AND NOT EXISTS(SELECT 1 FROM practice_assignments WHERE id=NEW.assignment_id AND created_at=NEW.created_at AND created_by=NEW.created_by)) OR (NEW.version>1 AND EXISTS(SELECT 1 FROM practice_current WHERE assignment_id=NEW.assignment_id AND status='closed')) BEGIN SELECT RAISE(ABORT,'family version mismatch'); END;
CREATE TRIGGER practice_event_guard BEFORE INSERT ON practice_events WHEN NEW.revision!=(SELECT COALESCE(max(revision),0)+1 FROM practice_events WHERE assignment_id=NEW.assignment_id) OR NEW.version!=(SELECT max(version) FROM practice_versions WHERE assignment_id=NEW.assignment_id) OR (length(trim(NEW.note)) NOT BETWEEN 1 AND 1000 OR length(NEW.note)>1000) OR (NEW.action IN('create','revise','publish') AND NEW.created_by!=(SELECT owner_id FROM practice_assignments WHERE id=NEW.assignment_id)) OR (NEW.action IN('withdraw','close') AND NEW.created_by!=(SELECT owner_id FROM practice_assignments WHERE id=NEW.assignment_id) AND (SELECT role FROM users WHERE id=NEW.created_by)!='manager') OR (NEW.action IN('create','revise') AND NOT EXISTS(SELECT 1 FROM practice_versions WHERE assignment_id=NEW.assignment_id AND version=NEW.version AND base_sequence=NEW.sequence-1 AND created_at=NEW.created_at AND created_by=NEW.created_by)) OR (NEW.revision=1 AND (NEW.action!='create' OR NEW.version!=1 OR NEW.status!='draft' OR NEW.released_version IS NOT NULL)) OR (NEW.revision>1 AND NOT EXISTS(SELECT 1 FROM practice_current p WHERE p.assignment_id=NEW.assignment_id AND p.status!='closed' AND ((NEW.action='revise' AND NEW.version=p.version+1 AND NEW.status=p.status AND NEW.released_version IS p.released_version) OR (NEW.action='publish' AND NEW.version=p.version AND NEW.status='published' AND NEW.released_version=NEW.version AND (p.status!='published' OR p.released_version!=NEW.version)) OR (NEW.action='withdraw' AND p.status='published' AND NEW.status='withdrawn' AND NEW.version=p.version AND NEW.released_version IS p.released_version) OR (NEW.action='close' AND NEW.status='closed' AND NEW.version=p.version AND NEW.released_version IS CASE WHEN p.status='withdrawn' THEN NULL ELSE p.released_version END)))) BEGIN SELECT RAISE(ABORT,'family event transition mismatch'); END;
CREATE TRIGGER practice_publish_guard BEFORE INSERT ON practice_events WHEN NEW.action='publish' AND (NOT EXISTS(SELECT 1 FROM practice_assignments a JOIN guardian_links g ON g.customer_id=a.customer_id AND g.user_id=a.recipient_id JOIN users u ON u.id=g.user_id JOIN training_plan_events p ON p.plan_id=a.plan_id WHERE a.id=NEW.assignment_id AND g.active=1 AND u.active=1 AND u.role='guardian' AND p.plan_version=a.plan_version AND p.status='active' AND p.revision=(SELECT max(revision) FROM training_plan_events WHERE plan_id=a.plan_id)) OR NOT EXISTS(SELECT 1 FROM practice_versions WHERE assignment_id=NEW.assignment_id AND version=NEW.version AND created_at<=NEW.created_at)) BEGIN SELECT RAISE(ABORT,'family current publication source mismatch'); END;
CREATE TRIGGER practice_report_guard BEFORE INSERT ON practice_reports WHEN NEW.serial!=(SELECT COALESCE(max(serial),0)+1 FROM practice_reports WHERE assignment_id=NEW.assignment_id) OR NOT EXISTS(SELECT 1 FROM practice_current WHERE assignment_id=NEW.assignment_id AND status='published' AND revision=NEW.assignment_revision AND released_version=NEW.version) OR length(NEW.occurred_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.occurred_at) IS NOT NEW.occurred_at OR NEW.occurred_at>NEW.created_at OR (length(trim(NEW.feedback)) NOT BETWEEN 1 AND 1000 OR length(NEW.feedback)>1000) OR (length(trim(NEW.source_note)) NOT BETWEEN 1 AND 1000 OR length(NEW.source_note)>1000) OR ((NEW.source='guardian_self_report')!=((SELECT role FROM users WHERE id=NEW.created_by)='guardian')) OR (NEW.source='guardian_self_report' AND NOT EXISTS(SELECT 1 FROM practice_assignments a JOIN guardian_links g ON g.user_id=a.recipient_id AND g.customer_id=a.customer_id WHERE a.id=NEW.assignment_id AND a.recipient_id=NEW.created_by AND g.active=1)) BEGIN SELECT RAISE(ABORT,'family report source/publication mismatch'); END;
CREATE TRIGGER practice_review_guard BEFORE INSERT ON practice_reviews WHEN NEW.revision!=(SELECT COALESCE(max(revision),0)+1 FROM practice_reviews WHERE report_id=NEW.report_id) OR NOT EXISTS(SELECT 1 FROM practice_reports r JOIN practice_assignments a ON a.id=r.assignment_id WHERE r.id=NEW.report_id AND a.store_id=NEW.store_id AND a.owner_id=NEW.created_by AND r.created_at<=NEW.created_at) OR (length(trim(NEW.internal_note)) NOT BETWEEN 1 AND 1000 OR length(NEW.internal_note)>1000) OR (NEW.family_feedback IS NOT NULL AND (length(trim(NEW.family_feedback)) NOT BETWEEN 1 AND 1000 OR length(NEW.family_feedback)>1000)) OR (NEW.share_feedback=1 AND NOT EXISTS(SELECT 1 FROM practice_reports r JOIN practice_current p ON p.assignment_id=r.assignment_id WHERE r.id=NEW.report_id AND r.source='guardian_self_report' AND p.status='published')) OR (NEW.followup_task_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM practice_reports r JOIN practice_assignments a ON a.id=r.assignment_id JOIN work_tasks t ON t.customer_id=a.customer_id WHERE r.id=NEW.report_id AND t.id=NEW.followup_task_id AND t.store_id=a.store_id AND t.cycle_id=a.cycle_id AND t.revision=NEW.followup_revision AND t.created_at<=NEW.created_at)) BEGIN SELECT RAISE(ABORT,'family review/followup mismatch'); END;
CREATE TRIGGER reassessment_version_guard BEFORE INSERT ON training_reassessment_versions WHEN NEW.version!=(SELECT COALESCE(max(version),0)+1 FROM training_reassessment_versions WHERE reassessment_id=NEW.reassessment_id) OR NEW.base_sequence!=(SELECT COALESCE(max(sequence),0) FROM family_journal WHERE store_id=NEW.store_id) OR NEW.created_by!=(SELECT owner_id FROM training_reassessments WHERE id=NEW.reassessment_id) OR (NEW.version=1 AND NOT EXISTS(SELECT 1 FROM training_reassessments WHERE id=NEW.reassessment_id AND created_at=NEW.created_at AND created_by=NEW.created_by)) OR (NEW.version>1 AND EXISTS(SELECT 1 FROM reassessment_current WHERE reassessment_id=NEW.reassessment_id AND status='checked')) OR (length(trim(NEW.title)) NOT BETWEEN 1 AND 120 OR length(NEW.title)>120) OR (length(trim(NEW.source_note)) NOT BETWEEN 1 AND 1000 OR length(NEW.source_note)>1000) OR (length(trim(NEW.comparison_note)) NOT BETWEEN 1 AND 3000 OR length(NEW.comparison_note)>3000) OR (length(trim(NEW.assessment_note)) NOT BETWEEN 1 AND 3000 OR length(NEW.assessment_note)>3000) OR (length(trim(NEW.next_step)) NOT BETWEEN 1 AND 1000 OR length(NEW.next_step)>1000) OR (length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300) BEGIN SELECT RAISE(ABORT,'reassessment version mismatch'); END;
CREATE TRIGGER reassessment_event_guard BEFORE INSERT ON training_reassessment_events WHEN NEW.revision!=(SELECT COALESCE(max(revision),0)+1 FROM training_reassessment_events WHERE reassessment_id=NEW.reassessment_id) OR NEW.version!=(SELECT max(version) FROM training_reassessment_versions WHERE reassessment_id=NEW.reassessment_id) OR NEW.created_by!=(SELECT owner_id FROM training_reassessments WHERE id=NEW.reassessment_id) OR (length(trim(NEW.note)) NOT BETWEEN 1 AND 1000 OR length(NEW.note)>1000) OR (NEW.action IN('create','revise') AND NOT EXISTS(SELECT 1 FROM training_reassessment_versions WHERE reassessment_id=NEW.reassessment_id AND version=NEW.version AND base_sequence=NEW.sequence-1 AND created_at=NEW.created_at AND created_by=NEW.created_by)) OR (NEW.revision=1 AND (NEW.action!='create' OR NEW.version!=1 OR NEW.status!='draft')) OR (NEW.revision>1 AND NOT EXISTS(SELECT 1 FROM reassessment_current p WHERE p.reassessment_id=NEW.reassessment_id AND p.status='draft' AND ((NEW.action='revise' AND NEW.version=p.version+1 AND NEW.status='draft') OR (NEW.action='check' AND NEW.version=p.version AND NEW.status='checked')))) BEGIN SELECT RAISE(ABORT,'reassessment transition mismatch'); END;

CREATE TRIGGER reassessment_manifest_shape BEFORE INSERT ON training_reassessment_versions WHEN json_type(NEW.manifest_json) IS NOT 'object' OR (SELECT count(*) FROM json_each(NEW.manifest_json))!=4 OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json) WHERE key NOT IN('sessions','reports','documents','followup')) OR json_type(NEW.manifest_json,'$.sessions') IS NOT 'array' OR json_type(NEW.manifest_json,'$.reports') IS NOT 'array' OR json_type(NEW.manifest_json,'$.documents') IS NOT 'array' OR json_type(NEW.manifest_json,'$.followup') NOT IN('null','object') OR json_array_length(NEW.manifest_json,'$.sessions')>30 OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.sessions') j WHERE j.type!='object' OR (SELECT count(*) FROM json_each(j.value))!=2 OR json_type(j.value,'$.id') IS NOT 'text' OR length(json_extract(j.value,'$.id')) NOT BETWEEN 1 AND 100 OR json_type(j.value,'$.revision') IS NOT 'integer' OR json_extract(j.value,'$.revision') NOT BETWEEN 1 AND 1000000000 OR EXISTS(SELECT 1 FROM json_each(j.value) WHERE key NOT IN('id','revision'))) OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.sessions') GROUP BY json_extract(value,'$.id') HAVING count(*)>1) OR json_array_length(NEW.manifest_json,'$.reports')>30 OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.reports') j WHERE j.type!='object' OR (SELECT count(*) FROM json_each(j.value))!=2 OR json_type(j.value,'$.id') IS NOT 'text' OR length(json_extract(j.value,'$.id')) NOT BETWEEN 1 AND 100 OR json_type(j.value,'$.review_revision') IS NOT 'integer' OR json_extract(j.value,'$.review_revision') NOT BETWEEN 0 AND 1000000000 OR EXISTS(SELECT 1 FROM json_each(j.value) WHERE key NOT IN('id','review_revision'))) OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.reports') GROUP BY json_extract(value,'$.id') HAVING count(*)>1) OR json_array_length(NEW.manifest_json,'$.documents')>30 OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.documents') WHERE type!='text' OR length(value) NOT BETWEEN 1 AND 100) OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.documents') GROUP BY value HAVING count(*)>1) OR (json_type(NEW.manifest_json,'$.followup')='object' AND ((SELECT count(*) FROM json_each(NEW.manifest_json,'$.followup'))!=2 OR json_type(NEW.manifest_json,'$.followup.id') IS NOT 'text' OR length(json_extract(NEW.manifest_json,'$.followup.id')) NOT BETWEEN 1 AND 100 OR json_type(NEW.manifest_json,'$.followup.revision') IS NOT 'integer' OR json_extract(NEW.manifest_json,'$.followup.revision') NOT BETWEEN 1 AND 1000000000 OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.followup') WHERE key NOT IN('id','revision')))) BEGIN SELECT RAISE(ABORT,'reassessment manifest shape mismatch'); END;
CREATE TRIGGER reassessment_manifest_source BEFORE INSERT ON training_reassessment_versions WHEN EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.sessions') j WHERE NOT EXISTS(SELECT 1 FROM training_sessions s JOIN training_session_events e ON e.session_id=s.id JOIN training_reassessments a ON a.id=NEW.reassessment_id WHERE s.id=json_extract(j.value,'$.id') AND e.revision=json_extract(j.value,'$.revision') AND e.revision=(SELECT max(revision) FROM training_session_events WHERE session_id=s.id) AND e.status IN('recorded','reviewed','aborted') AND s.customer_id=a.customer_id AND s.store_id=a.store_id AND s.plan_id=a.plan_id AND e.created_at<=NEW.created_at)) OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.reports') j WHERE NOT EXISTS(SELECT 1 FROM practice_reports r JOIN practice_assignments p ON p.id=r.assignment_id JOIN training_reassessments a ON a.id=NEW.reassessment_id WHERE r.id=json_extract(j.value,'$.id') AND p.customer_id=a.customer_id AND p.plan_id=a.plan_id AND r.store_id=a.store_id AND r.sequence<=NEW.base_sequence AND r.created_at<=NEW.created_at AND json_extract(j.value,'$.review_revision')=(SELECT coalesce(max(revision),0) FROM practice_reviews WHERE report_id=r.id AND sequence<=NEW.base_sequence))) OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.documents') j WHERE NOT EXISTS(SELECT 1 FROM document_versions d JOIN training_reassessments a ON a.id=NEW.reassessment_id WHERE d.id=j.value AND d.customer_id=a.customer_id AND d.created_at<=NEW.created_at)) OR (json_type(NEW.manifest_json,'$.followup')='object' AND NOT EXISTS(SELECT 1 FROM work_tasks t JOIN training_reassessments a ON a.id=NEW.reassessment_id JOIN task_events e ON e.task_id=t.id AND e.revision=t.revision WHERE t.id=json_extract(NEW.manifest_json,'$.followup.id') AND t.revision=json_extract(NEW.manifest_json,'$.followup.revision') AND t.customer_id=a.customer_id AND t.store_id=a.store_id AND t.cycle_id=a.cycle_id AND e.created_at<=NEW.created_at)) BEGIN SELECT RAISE(ABORT,'reassessment manifest source mismatch'); END;
CREATE TRIGGER reassessment_check_source BEFORE INSERT ON training_reassessment_events WHEN NEW.action='check' AND EXISTS(SELECT 1 FROM training_reassessment_versions v WHERE v.reassessment_id=NEW.reassessment_id AND v.version=NEW.version AND (EXISTS(SELECT 1 FROM json_each(v.manifest_json,'$.sessions') j WHERE NOT EXISTS(SELECT 1 FROM training_sessions s JOIN training_session_events e ON e.session_id=s.id JOIN training_reassessments a ON a.id=NEW.reassessment_id WHERE s.id=json_extract(j.value,'$.id') AND e.revision=json_extract(j.value,'$.revision') AND e.revision=(SELECT max(revision) FROM training_session_events WHERE session_id=s.id) AND e.status IN('recorded','reviewed','aborted') AND s.customer_id=a.customer_id AND s.store_id=a.store_id AND s.plan_id=a.plan_id AND e.created_at<=NEW.created_at)) OR EXISTS(SELECT 1 FROM json_each(v.manifest_json,'$.reports') j WHERE NOT EXISTS(SELECT 1 FROM practice_reports r JOIN practice_assignments p ON p.id=r.assignment_id JOIN training_reassessments a ON a.id=NEW.reassessment_id WHERE r.id=json_extract(j.value,'$.id') AND p.customer_id=a.customer_id AND p.plan_id=a.plan_id AND r.store_id=a.store_id AND r.sequence<=NEW.sequence-1 AND r.created_at<=NEW.created_at AND json_extract(j.value,'$.review_revision')=(SELECT coalesce(max(revision),0) FROM practice_reviews WHERE report_id=r.id AND sequence<=NEW.sequence-1))) OR EXISTS(SELECT 1 FROM json_each(v.manifest_json,'$.documents') j WHERE NOT EXISTS(SELECT 1 FROM document_versions d JOIN training_reassessments a ON a.id=NEW.reassessment_id WHERE d.id=j.value AND d.customer_id=a.customer_id AND d.created_at<=NEW.created_at)) OR (json_type(v.manifest_json,'$.followup')='object' AND NOT EXISTS(SELECT 1 FROM work_tasks t JOIN training_reassessments a ON a.id=NEW.reassessment_id JOIN task_events e ON e.task_id=t.id AND e.revision=t.revision WHERE t.id=json_extract(v.manifest_json,'$.followup.id') AND t.revision=json_extract(v.manifest_json,'$.followup.revision') AND t.customer_id=a.customer_id AND t.store_id=a.store_id AND t.cycle_id=a.cycle_id AND e.created_at<=NEW.created_at)))) BEGIN SELECT RAISE(ABORT,'reassessment check source mismatch'); END;
CREATE TRIGGER practice_creation_current_plan BEFORE INSERT ON practice_assignments WHEN NOT EXISTS(SELECT 1 FROM training_plan_events e WHERE e.plan_id=NEW.plan_id AND e.plan_version=NEW.plan_version AND e.status='active' AND e.revision=(SELECT max(revision) FROM training_plan_events WHERE plan_id=NEW.plan_id)) BEGIN SELECT RAISE(ABORT,'practice current plan mismatch'); END;
CREATE TRIGGER practice_share_recipient BEFORE INSERT ON practice_reviews WHEN NEW.share_feedback=1 AND NOT EXISTS(SELECT 1 FROM practice_reports r JOIN practice_assignments a ON a.id=r.assignment_id JOIN users u ON u.id=a.recipient_id JOIN guardian_links g ON g.user_id=u.id AND g.customer_id=a.customer_id LEFT JOIN user_security x ON x.user_id=u.id WHERE r.id=NEW.report_id AND u.active=1 AND u.role='guardian' AND g.active=1 AND coalesce(x.must_change_password,0)=0) BEGIN SELECT RAISE(ABORT,'practice feedback recipient mismatch'); END;

CREATE TRIGGER practice_recipient_security BEFORE INSERT ON practice_assignments WHEN EXISTS(SELECT 1 FROM user_security WHERE user_id=NEW.recipient_id AND must_change_password=1) BEGIN SELECT RAISE(ABORT,'practice recipient security mismatch'); END;
CREATE TRIGGER practice_publish_security BEFORE INSERT ON practice_events WHEN NEW.action='publish' AND EXISTS(SELECT 1 FROM practice_assignments a JOIN user_security x ON x.user_id=a.recipient_id WHERE a.id=NEW.assignment_id AND x.must_change_password=1) BEGIN SELECT RAISE(ABORT,'practice recipient security mismatch'); END;

CREATE TRIGGER reassessment_creation_current_plan BEFORE INSERT ON training_reassessments WHEN NOT EXISTS(SELECT 1 FROM training_plan_events e WHERE e.plan_id=NEW.plan_id AND e.plan_version=NEW.plan_version AND e.status='active' AND e.revision=(SELECT max(revision) FROM training_plan_events WHERE plan_id=NEW.plan_id)) BEGIN SELECT RAISE(ABORT,'reassessment current plan mismatch'); END;
